import{_ as r,C as o,o as i,c as n,j as e,a as s,E as l,al as d}from"./chunks/framework.7vp1BMOE.js";const u="/px4_user_guide/assets/zenfc_h743.BgRWDfMB.png",h="/px4_user_guide/assets/zenfc_h743_dimensions.D8Gq0NLM.png",c="/px4_user_guide/assets/zenfc_h743_layout_front.DSN-jgEa.png",p="/px4_user_guide/assets/zenfc_h743_layout_back.B0E9rIN-.png",g="/px4_user_guide/assets/zenfc_h743_pinouts_front.DCFJ43FE.png",m="/px4_user_guide/assets/zenfc_h743_pinouts_back.CIjKKgkv.png",x=JSON.parse('{"title":"ZenFC H743","description":"","frontmatter":{},"headers":[],"relativePath":"en/flight_controller/zenfc_h743.md","filePath":"en/flight_controller/zenfc_h743.md"}'),f={name:"en/flight_controller/zenfc_h743.md"};function _(b,t,y,S,C,P){const a=o("Badge");return i(),n("div",null,[t[0]||(t[0]=e("h1",{id:"zenfc-h743",tabindex:"-1"},[s("ZenFC H743 "),e("a",{class:"header-anchor",href:"#zenfc-h743","aria-label":'Permalink to "ZenFC H743"'},"​")],-1)),l(a,{type:"tip",text:"PX4 main (v2.0)"}),t[1]||(t[1]=d('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 does not manufacture this (or any) autopilot. Contact the <a href="https://www.zenithratech.com/contact" target="_blank" rel="noreferrer">manufacturer</a> for hardware support or compliance issues.</p></div><p>The <em>ZenFC H743</em> is a flight controller designed by Zenithra Tech. It is built around the STM32H743 processor with dual Bosch BMI088 IMUs for sensor redundancy, an onboard barometer, and an integrated OSD.</p><p><img src="'+u+'" alt="ZenFC H743 Flight Controller"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This flight controller is <a href="./../flight_controller/autopilot_manufacturer_supported">manufacturer supported</a>.</p></div><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ul><li><strong>MCU:</strong><ul><li>STM32H743VIT6 (32-bit Arm® Cortex®-M7, 480 MHz)</li></ul></li><li><strong>IMU:</strong><ul><li>2x Bosch BMI088 (accel + gyro, independent SPI buses for redundancy)</li></ul></li><li><strong>Barometer:</strong><ul><li>Bosch BMP388</li></ul></li><li><strong>OSD:</strong><ul><li>Onboard AT7456E OSD chip</li></ul></li><li><strong>Interfaces:</strong><ul><li>7x UARTs</li><li>1x CAN</li><li>2x external I2C (I2C1 with GPS connector and dedicated I2C2 connector)</li><li>8x PWM outputs (Dshot supported)</li><li>microSD card slot</li><li>1x USB Type-C</li></ul></li><li><strong>Power:</strong><ul><li>2x ADC (V_BAT &amp; current sense)</li><li>Battery Input range - 2S-6S</li><li>BEC Outputs <ul><li>9V 3A cont.</li><li>5V 3A cont.</li></ul></li></ul></li></ul><h2 id="dimensions" tabindex="-1">Dimensions <a class="header-anchor" href="#dimensions" aria-label="Permalink to &quot;Dimensions&quot;">​</a></h2><ul><li><strong>Mounting:</strong> 30.5 mm x 30.5 mm /Φ4mm hole</li><li><strong>Dimensions:</strong> 35mm x 35mm x 8mm</li><li><strong>Weight:</strong> 9g</li></ul><p><img src="'+h+'" alt="ZenFC H743 Dimensions"></p><h2 id="where-to-buy" tabindex="-1">Where to Buy <a class="header-anchor" href="#where-to-buy" aria-label="Permalink to &quot;Where to Buy&quot;">​</a></h2><p>Order from <a href="https://www.zenithratech.com/solutions/components" target="_blank" rel="noreferrer">Zenithra Tech</a>.</p><h2 id="flight-controller-layout" tabindex="-1">Flight Controller Layout <a class="header-anchor" href="#flight-controller-layout" aria-label="Permalink to &quot;Flight Controller Layout&quot;">​</a></h2><p><img src="'+c+'" alt="ZenFC H743 Layout Front"></p><p><img src="'+p+'" alt="ZenFC H743 Layout Back"></p><h2 id="serial-port-mapping" tabindex="-1">Serial Port Mapping <a class="header-anchor" href="#serial-port-mapping" aria-label="Permalink to &quot;Serial Port Mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UART</th><th>Device</th><th>PX4 Port</th></tr></thead><tbody><tr><td>USART1</td><td>/dev/ttyS0</td><td>GPS1</td></tr><tr><td>USART2</td><td>/dev/ttyS1</td><td>TEL3</td></tr><tr><td>USART3</td><td>/dev/ttyS2</td><td>TEL4</td></tr><tr><td>UART5</td><td>/dev/ttyS3</td><td>TEL1</td></tr><tr><td>USART6</td><td>/dev/ttyS4</td><td>RC</td></tr><tr><td>UART7</td><td>/dev/ttyS5</td><td>TEL2</td></tr><tr><td>UART8</td><td>/dev/ttyS6</td><td>UART6</td></tr></tbody></table><h2 id="connectors-pinout" tabindex="-1">Connectors &amp; Pinout <a class="header-anchor" href="#connectors-pinout" aria-label="Permalink to &quot;Connectors &amp; Pinout&quot;">​</a></h2><p>Board uses JST SH connectors for all interfaces.</p><p><img src="'+g+'" alt="ZenFC H743 Pinouts Front"></p><p><img src="'+m+'" alt="ZenFC H743 Pinouts Back"></p><p><strong>Note</strong> - SBus pin on DJI O3/O4 port is internally connected to RX6 (<code>RCIN</code>).</p><h3 id="pwm-outputs" tabindex="-1">PWM Outputs <a class="header-anchor" href="#pwm-outputs" aria-label="Permalink to &quot;PWM Outputs&quot;">​</a></h3><p>The 8 outputs are in 3 groups:</p><ul><li>Outputs 1-4 in group1</li><li>Outputs 5-6 in group2</li><li>Outputs 7-8 in group3</li></ul><p><strong>Note</strong>:</p><ul><li>All outputs support PWM and <a href="./../peripherals/dshot">DShot</a> protocol. Outputs 1-6 and 8 support &quot;bidirectional DShot&quot; (or &quot;BDShot&quot;) telemetry.</li><li>Outputs 1-4 default to DShot300 (<a href="./../advanced_config/parameter_reference#PWM_MAIN_TIM0">PWM_MAIN_TIM0</a> = <code>-4</code>); outputs 5-6 and 7-8 default to PWM at 400 Hz.</li><li>Each group&#39;s protocol can be changed independently using the corresponding <code>PWM_MAIN_TIMx</code> parameter, including to <a href="./../peripherals/dshot#bidirectional-dshot-telemetry">Bidirectional DShot</a> (BDShot) for ESC telemetry.</li></ul><h3 id="debug-port" tabindex="-1">Debug Port <a class="header-anchor" href="#debug-port" aria-label="Permalink to &quot;Debug Port&quot;">​</a></h3><p>This board does not configure a dedicated UART as a system console. Use the <a href="./../debug/mavlink_shell">MAVLink Shell</a> over USB for console/NSH access using QGroundControl.</p><p><strong>SWD</strong></p><p>The board features a <a href="./../debug/swd_debug"><strong>4-pin SWD Debug</strong></a> interface (3V3 / SWCLK / SWDIO / GND) for hardware debugging.</p><h2 id="radio-control" tabindex="-1">Radio Control <a class="header-anchor" href="#radio-control" aria-label="Permalink to &quot;Radio Control&quot;">​</a></h2><p>A <a href="./../getting_started/rc_transmitter_receiver">Radio Control (RC) system</a> is required if you want to manually control your vehicle (PX4 does not require a radio system for autonomous flight modes). See <a href="./../modules/modules_driver_radio_control">Radio Control modules</a> for the list of supported protocols.</p><p>RC input is mapped to <strong>USART6</strong> (<code>/dev/ttyS4</code>, <code>RC</code> port). The port supports both single-wire inverted SBUS and full-duplex protocols with telemetry return (such as CRSF), and the receiver protocol is auto-detected by default (<a href="./../advanced_config/parameter_reference#RC_INPUT_PROTO">RC_INPUT_PROTO</a> = <code>-1</code>).</p><h2 id="px4-configuration" tabindex="-1">PX4 Configuration <a class="header-anchor" href="#px4-configuration" aria-label="Permalink to &quot;PX4 Configuration&quot;">​</a></h2><p>In addition to the <a href="./../config/">basic configuration</a>, the following parameter is important:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Setting</th></tr></thead><tbody><tr><td><a href="./../advanced_config/parameter_reference#SYS_HAS_MAG">SYS_HAS_MAG</a></td><td>Disabled by default since the board has no internal magnetometer. Enable it if you attach an external mag.</td></tr></tbody></table><h2 id="building-firmware" tabindex="-1">Building Firmware <a class="header-anchor" href="#building-firmware" aria-label="Permalink to &quot;Building Firmware&quot;">​</a></h2><p>To <a href="./../dev_setup/building_px4">build PX4</a> for this target:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zenfc_h743_default</span></span></code></pre></div><h2 id="installing-px4-firmware" tabindex="-1">Installing PX4 Firmware <a class="header-anchor" href="#installing-px4-firmware" aria-label="Permalink to &quot;Installing PX4 Firmware&quot;">​</a></h2><p>The firmware can be installed in any of the normal ways:</p><ul><li><p>Build and upload the source:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zenfc_h743_default</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upload</span></span></code></pre></div></li><li><p><a href="./../config/firmware">Load the firmware</a> using <em>QGroundControl</em>. You can use either pre-built firmware or your own custom firmware.</p></li></ul><p>The board uses the standard PX4 bootloader, so it follows the same generic LED indications as most other boards (Red = Bootloader/Error, Blue = Active/Activity, Green = Powered).</p><h2 id="further-info" tabindex="-1">Further info <a class="header-anchor" href="#further-info" aria-label="Permalink to &quot;Further info&quot;">​</a></h2><ul><li><a href="https://www.zenithratech.com/contact" target="_blank" rel="noreferrer">Zenithra Tech</a></li></ul>',45))])}const T=r(f,[["render",_]]);export{x as __pageData,T as default};
